def box_size(lo, hi):
    total = 1
    for low, high in zip(lo, hi):
        width = high - low + 1
        if low <= PADDING <= high:
            width -= 1
        if width <= 0:
            return 0
        total *= width
        if total > 1 << 62:
            return total
    return total


def drop_contained(boxes):
    """Drop boxes whose key set is a subset of another surviving box.

    Box A lies inside box B exactly when every coordinate interval of A sits
    inside B's, because the padding hole is defined per coordinate.  Boxes are
    already distinct here, so containment is a strict subset relation and the
    survivors cover the same key union.
    """
    import numpy as np
    groups = {}
    for position, box in enumerate(boxes):
        groups.setdefault(box[1], []).append(position)
    doomed = set()
    for length, members in groups.items():
        count = len(members)
        if count < 2:
            continue
        if count > 16:
            low = np.asarray([boxes[m][2] for m in members], dtype=np.int16)
            high = np.asarray([boxes[m][3] for m in members], dtype=np.int16)
            inside = np.ones((count, count), dtype=bool)
            for coordinate in range(length):
                inside &= low[:, coordinate][:, None] >= low[None, :, coordinate]
                inside &= high[:, coordinate][:, None] <= high[None, :, coordinate]
            np.fill_diagonal(inside, False)
            for row in np.flatnonzero(inside.any(axis=1)):
                doomed.add(members[int(row)])
            continue
        for row in range(count):
            lo = boxes[members[row]][2]
            hi = boxes[members[row]][3]
            for other in range(count):
                if other == row:
                    continue
                olo = boxes[members[other]][2]
                ohi = boxes[members[other]][3]
                if all(olo[i] <= lo[i] and hi[i] <= ohi[i] for i in range(length)):
                    doomed.add(members[row])
                    break
    return [box for position, box in enumerate(boxes) if position not in doomed]


def enumerate_keys(boxes, limit):
    """Exact distinct-key census, stopping as soon as the pool is exceeded."""
    keys = set()
    boxes.sort(key=lambda box: -box[0])
    for _, length, lo, hi in boxes:
        axes = []
        empty = False
        for low, high in zip(lo, hi):
            allowed = tuple(value for value in range(low, high + 1) if value != PADDING)
            if not allowed:
                empty = True
                break
            axes.append(allowed)
        if empty:
            continue
        for key in product(*axes):
            keys.add(key)
            if len(keys) >= limit:
                return limit
    return len(keys)


def exact_entry_count(patterns, capacity):
    """min(distinct exact keys, capacity+1) over kept-cluster Cartesian boxes."""
    limit = capacity + 1
    boxes = []
    seen = set()
    for length, lo, hi in patterns:
        signature = (length, lo, hi)
        if signature in seen:
            continue
        seen.add(signature)
        size = box_size(lo, hi)
        if size == 0:
            continue
        if size > capacity:
            # One box alone exceeds the pool: the certificate clips at cap+1.
            return limit
        boxes.append((size, length, lo, hi))
    if not boxes:
        return 0
    if len(boxes) > 1 and sum(box[0] for box in boxes) > 65536:
        boxes = drop_contained(boxes)
    return enumerate_keys(boxes, limit)
